```app
// Traffic light: green 3 s, yellow 1 s, red 3 s, round and round; Pause stops it and starts it again.
// icon: fill 8 2 16 2 16 22 8 22 dot 12 7 3 dot 12 12 3 dot 12 17 3
state phase = 0;   // 0 green, 1 yellow, 2 red
state t = 0;       // ms gone by in this phase
state speed = 100; // ms a tick; 0 while paused

// How long a phase lasts.
fn dur(p: int) -> int {
  if p == 1 { return 1000; }
  return 3000;
}

// A lamp's color: lit in its own hue, gray when not.
fn lamp(p: int) -> int {
  if phase == p {
    if p == 0 { return 2; }
    if p == 1 { return 3; }
    return 1;
  }
  return 8;
}

// The light, drawn anew from what it remembers: a dark housing and three lamps.
fn scene() {
  rect(34, 8, 52, 164, 9);
  ring(60, 40, 24, 2, 10);
  ring(60, 90, 24, 2, 10);
  ring(60, 140, 24, 2, 10);
  circle(60, 40, 20, lamp(2));
  circle(60, 90, 20, lamp(1));
  circle(60, 140, 20, lamp(0));
  if speed == 0 { text("Paused", 60, 178, 8, 10); }
}

label "Traffic light";
canvas 120, 190, scene();
row {
  button "Pause" {
    if speed == 0 { speed = 100; } else { speed = 0; }
  }
  if phase == 0 { label "Green"; }
  if phase == 1 { label "Yellow"; }
  if phase == 2 { label "Red"; }
}
every speed {
  t += speed;
  if t >= dur(phase) {
    t = 0;
    phase = (phase + 1) % 3;
  }
}
```

