```app
// Guess: I pick a secret whole number from 1 to 100. Type a guess and press Guess; I say
// Too high, Too low or Correct and count tries. New game picks a new number.
// icon: ring 12 12 9 ring 12 12 5 dot 12 12 2
state secret = 0;      // the number to guess, 1 to 100
state count = 0;       // guesses so far
state msg = "";        // what the last guess heard back
state guess = "";      // the text in the input
state lo = 1;          // the lowest it could still be
state hi = 100;        // the highest it could still be
state over = false;    // guessed right, or a new game waiting
saved state best = 0;  // fewest tries a win took

// The range still possible, drawn as a bar: gray gone, accent left, the guess a mark.
fn scene() {
  rect(0, 0, 160, 36, 0);
  rect(10, 14, 140, 8, 8);
  if hi >= lo { rect(10 + (lo - 1) * 140 / 99, 14, max(2, (hi - lo + 1) * 140 / 99), 8, 11); }
  if count > 0 && !over {
    let g = parse(guess, 0);
    if g >= 1 && g <= 100 { rect(9 + g * 140 / 99, 10, 3, 16, 1); }
  }
  text(lo + "–" + hi, 80, 30, 6, 10);
}

fn start() {
  secret = 1 + random(100);
  count = 0;
  msg = "";
  guess = "";
  lo = 1;
  hi = 100;
  over = false;
}

fn say(s: string) { msg = s; }

label "Guess the number";
row {
  input guess;
  button "Guess" {
    if over { say("Press New game"); }
    else {
      let g = parse(guess, 0);
      if g < 1 || g > 100 || g != parse(guess, -1) { say("A whole number, 1 to 100"); }
      else {
        count += 1;
        if g < secret { say("Too low"); if g >= lo { lo = g + 1; } }
        else if g > secret { say("Too high"); if g <= hi { hi = g - 1; } }
        else {
          say("Correct! " + count + (count == 1 ? " try" : " tries"));
          over = true;
          if best == 0 || count < best { best = count; }
        }
      }
    }
  }
}
label msg;
canvas 160, 40, scene();
row {
  if over { button "New game" { start(); } }
  label "Guesses: " + count + "   Best: " + best;
}
