```app
// Poll: tap Cats, Dogs or Birds to add a vote; the chart shows one bar per option on a
// baseline, as tall as its votes allow, with each count above it.
// icon: fill 4 12 8 12 8 20 4 20 fill 10 8 14 8 14 20 10 20 fill 16 4 20 4 20 20 20 16 20
state cats = 0;
state dogs = 0;
state birds = 0;

// A bar's height: twice its votes, shrunk together only so the tallest still fits.
fn height(v: int) -> int {
  let m = max(cats, max(dogs, birds));
  if m <= 50 { return v * 2; }
  return v * 100 / m;
}

// One bar, its count above it and its name below the baseline.
fn bar(v: int, x: int, color: int, name: string) {
  let h = height(v);
  rect(x, 110 - h, 30, h, color);
  text(v, x + 15, 110 - h - 7, 8, 9);
  text(name, x + 15, 116, 6, 10);
}

fn scene() {
  rect(10, 110, 140, 1, 8);
  bar(cats, 20, 1, "Cats");
  bar(dogs, 65, 4, "Dogs");
  bar(birds, 110, 2, "Birds");
}

label "Poll";
row {
  button "Cats" { cats += 1; }
  button "Dogs" { dogs += 1; }
  button "Birds" { birds += 1; }
}
canvas 160, 120, scene();
