```app
// Tic-tac-toe: two players, one board; tap a square to place X or O, X first; New game empties it.
// icon: line 5 5 12 12 line 12 5 5 12 ring 18 17 5
state board = [0; 9];   // 0 empty, 1 X, 2 O
state xturn = true;      // whose move: true X, false O
state winner = 0;        // 0 playing, 1 X wins, 2 O wins, 3 draw

fn win(p: int) -> bool {
  if board[0] == p && board[1] == p && board[2] == p { return true; }
  if board[3] == p && board[4] == p && board[5] == p { return true; }
  if board[6] == p && board[7] == p && board[8] == p { return true; }
  if board[0] == p && board[3] == p && board[6] == p { return true; }
  if board[1] == p && board[4] == p && board[7] == p { return true; }
  if board[2] == p && board[5] == p && board[8] == p { return true; }
  if board[0] == p && board[4] == p && board[8] == p { return true; }
  if board[2] == p && board[4] == p && board[6] == p { return true; }
  return false;
}

fn full() -> bool {
  for i in 0..9 {
    if board[i] == 0 { return false; }
  }
  return true;
}

fn place(i: int) {
  if winner != 0 || board[i] != 0 { return; }
  if xturn { board[i] = 1; } else { board[i] = 2; }
  if win(1) { winner = 1; return; }
  if win(2) { winner = 2; return; }
  if full() { winner = 3; return; }
  xturn = !xturn;
}

fn newgame() {
  for i in 0..9 { board[i] = 0; }
  xturn = true;
  winner = 0;
}

// An X or an O in square (x, y), 40 units wide.
fn drawmark(x: int, y: int, p: int) {
  if p == 1 {
    line(x + 10, y + 10, x + 30, y + 30, 4, 9);
    line(x + 30, y + 10, x + 10, y + 30, 4, 9);
  }
  if p == 2 { ring(x + 20, y + 20, 11, 4, 9); }
}

fn scene() {
  line(40, 4, 40, 116, 2, 8);
  line(80, 4, 80, 116, 2, 8);
  line(4, 40, 116, 40, 2, 8);
  line(4, 80, 116, 80, 2, 8);
  for i in 0..9 { drawmark((i % 3) * 40, (i / 3) * 40, board[i]); }
  if winner == 1 { text("X wins", 60, 60, 12, 1); }
  if winner == 2 { text("O wins", 60, 60, 12, 4); }
  if winner == 3 { text("Draw", 60, 60, 12, 10); }
}

label "Tic-tac-toe";
if winner == 0 {
  if xturn { label "X to move"; } else { label "O to move"; }
}
canvas 120, 120, scene() { place((y / 40) * 3 + x / 40); }
button "New game" { newgame(); }
```

```app
// Connect Four: tap a column to drop your disc (Red first, then Yellow); four in a line wins.
// icon: loop 4 4 20 4 20 20 4 20 dot 8 8 4 dot 16 8 4 dot 8 16 4 dot 16 16 4
state board = [0; 42];      // 7 x 6: 0 empty, 1 red, 2 yellow; y 0 is the top row
state red = true;           // whose move it is
state over = false;         // a win or a full board
state won = 0;              // 1 red, 2 yellow, 0 a draw
state win = [0; 4];         // the four squares of the winning line

fn at(x: int, y: int) -> int { return y * 7 + x; }

// How many discs of color v run on from (x, y) one way.
fn run(x: int, y: int, dx: int, dy: int, v: int) -> int {
  let n = 0;
  let cx = x;
  let cy = y;
  for i in 0..3 {
    cx += dx;
    cy += dy;
    if cx < 0 || cx >= 7 || cy < 0 || cy >= 6 { return n; }
    if board[at(cx, cy)] != v { return n; }
    n += 1;
  }
  return n;
}

// The color at (x, y) as a square color.
fn sq(x: int, y: int) -> int { return board[at(x, y)]; }

// Whether (x, y) is one of the winning squares.
fn wincell(x: int, y: int) -> bool {
  for i in 0..4 {
    if win[i] == at(x, y) { return true; }
  }
  return false;
}

// After a drop of v at (x, y): a win fills win and returns v, else 0.
fn check(x: int, y: int, v: int) -> int {
  let ds = [1, 0, 1, 1];
  let dys = [0, 1, 1, -1];
  for d in 0..4 {
    let a = run(x, y, ds[d], dys[d], v);
    let b = run(x, y, -ds[d], -dys[d], v);
    if a + b >= 3 {
      win[0] = at(x, y);
      for i in 0..a { win[i + 1] = at(x + ds[d] * (i + 1), y + dys[d] * (i + 1)); }
      for i in 0..b { win[a + i + 1] = at(x - ds[d] * (i + 1), y - dys[d] * (i + 1)); }
      return v;
    }
  }
  return 0;
}

// Drop the player's disc into column c, lowest empty square; then look for a win.
fn drop(c: int) {
  if over { return; }
  let y = -1;
  for j in 0..6 {
    if sq(c, j) == 0 { y = j; }
  }
  if y < 0 { return; }                 // the column is full
  let v = 1;
  if !red { v = 2; }
  board[at(c, y)] = v;
  let w = check(c, y, v);
  if w != 0 {
    over = true;
    won = w;
    return;
  }
  let full = true;
  for i in 0..42 {
    if board[i] == 0 { full = false; }
  }
  if full {
    over = true;
    won = 0;
    return;
  }
  red = !red;
}

fn newgame() {
  for i in 0..42 { board[i] = 0; }
  red = true;
  over = false;
  won = 0;
  for i in 0..4 { win[i] = 0; }
}

// The board, 7 x 6 squares of 16 units, drawn from what the game remembers.
fn scene() {
  let cells = [0; 42];
  for i in 0..42 { cells[i] = board[i]; }
  pixels(cells, 0, 0, 7, 16);
  for x in 0..7 {
    for y in 0..6 {
      if wincell(x, y) { ring(x * 16 + 8, y * 16 + 8, 7, 2, 9); }
    }
  }
  if over {
    if won == 1 { text("Red wins", 56, 48, 12, 9); }
    else if won == 2 { text("Yellow wins", 56, 48, 12, 9); }
    else { text("Draw", 56, 48, 12, 9); }
  } else if red {
    text("Red to move", 56, 6, 7, 9);
  } else {
    text("Yellow to move", 56, 6, 7, 9);
  }
}

label "Connect Four";
canvas 112, 96, scene() { drop(x / 16); }
button "New game" { newgame(); }
```

```app
// Pomodoro: Start, Pause and Reset; 25:00 of work, then Break 5:00, then work again.
// icon: ring 12 12 9 line 12 12 12 5
state left = 1500;        // seconds left in this stretch
state brk = false;        // true on break
state speed = 0;          // ms a tick; 0 while paused
saved state done = 0;     // work stretches finished

fn total() -> int {
  if brk { return 300; }
  return 1500;
}

fn two(n: int) -> string {
  if n < 10 { return "0" + n; }
  return "" + n;
}

fn shown() -> string {
  return two(left / 60) + ":" + two(left % 60);
}

fn scene() {
  rect(20, 96, 120, 6, 10);
  rect(20, 96, 120 * left / total(), 6, 4);
  if brk {
    text("Break", 80, 22, 10, 2);
    rect(20, 96, 120 * left / total(), 6, 2);
  } else {
    text("Work", 80, 22, 10, 4);
  }
  text(shown(), 80, 60, 24, 9);
  if speed == 0 { text("paused", 80, 88, 7, 10); }
}

fn reset() {
  left = total();
}

every speed {
  left -= 1;
  if left <= 0 {
    if brk {
      brk = false;
    } else {
      brk = true;
      done += 1;
    }
    left = total();
  }
}

label "Pomodoro";
canvas 160, 120, scene();
row {
  if speed > 0 {
    button "Pause" { speed = 0; }
  } else {
    button "Start" { speed = 1000; }
  }
  button "Reset" { speed = 0; brk = false; left = 1500; }
}
label "Finished " + done;
```

```app
// Clock: a face with hour, minute and second hands, from 12:00:00, one second every 1000 ms.
// icon: ring 12 12 9 line 12 12 12 6 line 12 12 17 12 line 12 12 14 14
state sec = 0;              // seconds since 12:00:00
state run = false;

fn two(n: int) -> string {
  if n < 10 { return "0" + n; }
  return "" + n;
}

// The time as text, like 12:00:05.
fn clock() -> string {
  let h = (sec / 3600) % 12;
  if h == 0 { h = 12; }
  return h + ":" + two((sec / 60) % 60) + ":" + two(sec % 60);
}

// A hand's end: d degrees clockwise from 12, r units out from the center.
fn hx(d: int, r: int) -> int { return 80 + r * sin(d) / 1000; }
fn hy(d: int, r: int) -> int { return 60 - r * cos(d) / 1000; }

fn scene() {
  ring(80, 60, 50, 2, 9);
  for i in 0..12 { line(hx(i * 30, 44), hy(i * 30, 44), hx(i * 30, 50), hy(i * 30, 50), 1, 10); }
  line(80, 60, hx(sec / 120, 28), hy(sec / 120, 28), 3, 9);        // hour
  line(80, 60, hx(sec / 10, 40), hy(sec / 10, 40), 2, 9);          // minute
  line(80, 60, hx(sec * 6, 45), hy(sec * 6, 45), 1, 1);            // second
  circle(80, 60, 2, 9);
  text(clock(), 80, 116, 7, 9);
}

every 1000 {
  if run { sec += 1; }
}

label "Clock";
canvas 160, 120, scene();
row {
  if run { button "Stop" { run = false; } }
  if !run { button "Start" { run = true; } }
  label clock();
}
```

```app
// Calculator: tap the buttons; the display shows what you type, then the result. C clears.
// icon: line 4 4 4 20 line 4 12 9 12 line 15 4 11 12 11 20 line 14 15 20 20 line 20 15 14 20
state shown = "";          // what the display reads: the number typed, the result, or Error
state acc = 0;             // the number saved with the pending operator
state op = "";             // the pending operator, "" while none
state fresh = true;        // the next digit begins a new number
state wrong = false;       // an Error waits for C

// The value of what is typed.
fn typed() -> int {
  return parse(shown, 0);
}

// a op b, whole numbers; / rounds toward zero, and dividing by zero is Error.
fn pair(a: int, b: int, o: string) -> string {
  if o == "+" { return "" + (a + b); }
  if o == "-" { return "" + (a - b); }
  if o == "*" {
    if a != 0 && abs(b) > 9223372036854775807 / abs(a) { return "Error"; }
    return "" + (a * b);
  }
  if o == "/" {
    if b == 0 { return "Error"; }
    return "" + (a / b);
  }
  return "" + b;
}

// A digit joins what is typed, without a leading zero.
fn digit(d: string) {
  if wrong { return; }
  if fresh || shown == "0" {
    shown = d;
    fresh = false;
  } else {
    shown = shown + d;
  }
}

// An operator: it finishes the one before, so 12 + 7 + ... goes on from the sum.
fn operator(o: string) {
  if wrong { return; }
  if op != "" && !fresh {
    shown = pair(acc, typed(), op);
    if shown == "Error" { wrong = true; op = ""; return; }
    acc = typed();
  } else {
    acc = typed();
  }
  op = o;
  fresh = true;
}

// The equals: it finishes the pending operator and leaves the result.
fn equals() {
  if wrong || op == "" { return; }
  shown = pair(acc, typed(), op);
  op = "";
  fresh = true;
  if shown == "Error" { wrong = true; }
}

fn clearAll() {
  shown = "";
  acc = 0;
  op = "";
  fresh = true;
  wrong = false;
}

label "Calculator";
row {
  label shown;
}
row {
  button "7" { digit("7"); }
  button "8" { digit("8"); }
  button "9" { digit("9"); }
  button "/" { operator("/"); }
}
row {
  button "4" { digit("4"); }
