// Life: tap squares to seed them, Step advances one generation, Play/Pause runs it, Clear empties.
// icon: dot 12 12 9 dot 5 5 3 dot 19 5 3 dot 5 19 3 dot 19 19 3
state cells = [0; 400];   // 20 x 20: 1 alive, 0 dead
state speed = 0;          // ms a generation; 0 while paused

fn at(x: int, y: int) -> int { return y * 20 + x; }

// 1 if (x, y) is alive; off the board counts dead, the edges do not wrap.
fn alive(x: int, y: int) -> int {
  if x < 0 || x >= 20 || y < 0 || y >= 20 { return 0; }
  return cells[at(x, y)];
}

fn neighbors(x: int, y: int) -> int {
  return alive(x - 1, y - 1) + alive(x, y - 1) + alive(x + 1, y - 1)
       + alive(x - 1, y)                     + alive(x + 1, y)
       + alive(x - 1, y + 1) + alive(x, y + 1) + alive(x + 1, y + 1);
}

// One generation: 2 or 3 neighbors keeps a cell alive, 3 births a new one.
fn step() {
  let next = [0; 400];
  for y in 0..20 {
    for x in 0..20 {
      let n = neighbors(x, y);
      if n == 3 || (n == 2 && cells[at(x, y)] == 1) { next[at(x, y)] = 1; }
    }
  }
  for i in 0..400 { cells[i] = next[i]; }
}

fn scene() {
  pixels(cells, 0, 0, 20, 8);
  if speed == 0 { text("paused", 80, 96, 6, 10); }
}

