// Mines: tap a square to reveal it; the first tap is never a mine; a 0 clears its neighbours too.
// Flag toggles taps between revealing and flagging; all safe squares found says You win.
// icon: fill 12 12 12 15 15 12 15 15 12 12 fill 9 9 9 12 12 9 12 12 9 9 ring 12 12 4
state mines = [0; 81];
state shown = [0; 81];
state flags = [0; 81];
state started = false;
state over = false;
state won = false;
state flagMode = false;
saved state best = 0;

fn at(x: int, y: int) -> int { return y * 9 + x; }

// How many mines touch square i.
fn count(i: int) -> int {
  let x = i % 9;
  let y = i / 9;
  let n = 0;
  for dy in -1..2 {
    for dx in -1..2 {
      let nx = x + dx;
      let ny = y + dy;
      if nx >= 0 && nx < 9 && ny >= 0 && ny < 9 {
        n += mines[at(nx, ny)];
      }
    }
  }
  return n;
}

// 10 mines anywhere but square safe (the first tap) and its neighbours.
fn place(safe: int) {
  let n = 0;
  while n < 10 {
    let i = random(81);
    if i != safe && mines[i] == 0 && count(i) == 0 {
      mines[i] = 1;
      n += 1;
    }
  }
}

// Reveal square i, then any 0 clears its neighbours too (a pass over the board, again while
// any square newly shows).
fn reveal(i: int) {
  if over || won || shown[i] == 1 || flags[i] == 1 { return; }
  if !started {
    place(i);
    started = true;
  }
  if mines[i] == 1 {
    shown[i] = 1;
    over = true;
    return;
  }
  shown[i] = 1;
  let pass = 0;
  let changed = true;
  while changed && pass < 81 {
    changed = false;
    pass += 1;
    for j in 0..81 {
      if shown[j] == 1 && count(j) == 0 {
        let x = j % 9;
        let y = j / 9;
        for dy in -1..2 {
          for dx in -1..2 {
            let nx = x + dx;
            let ny = y + dy;
            if nx >= 0 && nx < 9 && ny >= 0 && ny < 9 {
              let k = at(nx, ny);
              if shown[k] == 0 && flags[k] == 0 {
                shown[k] = 1;
                changed = true;
              }
            }
          }
        }
      }
    }
  }
}

fn flag(i: int) {
  if over || won || shown[i] == 1 { return; }
  flags[i] = 1 - flags[i];
}

fn tap(i: int) {
  if over || won { return; }
  if flagMode { flag(i); return; }
  reveal(i);
}

