// Whether squares a and b touch (or are the same).
fn near(a: int, b: int) -> bool {
  if abs(a % 9 - b % 9) <= 1 && abs(a / 9 - b / 9) <= 1 { return true; }
  return false;
}

// 10 mines anywhere but square safe (the first tap) and its neighbours: the allowed squares
// shuffled by swaps, the first 10 mined.
