```app
// Memory: 16 cards, 8 pairs; tap a card to turn it up, find the pairs in few moves.
// icon: fill 4 4 11 4 11 11 4 11 ring 17 8 5 line 17 8 17 20
state cards = [0; 16];      // each card's pair, 0..7
state up = [false; 16];     // face up?
state found = [false; 16];  // matched, stays up
state first = -1;           // the first card of a pair being tried, -1 none
state moves = 0;
state left = 8;             // pairs still hidden
state delay = 0;            // ms until a wrong pair turns down; 0 the timer rests

fn deal() {
  for i in 0..16 { cards[i] = i / 2; }
  for i in 0..15 {                       // shuffle by swaps
    let j = i + random(16 - i);
    let t = cards[i];
    cards[i] = cards[j];
    cards[j] = t;
  }
}

fn start() {
  deal();
  for i in 0..16 { up[i] = false; found[i] = false; }
  first = -1;
  moves = 0;
  left = 8;
  delay = 0;
}

// One card's glyph, drawn on its face: a shape in the pair's color.
fn glyph(p: int, cx: int, cy: int) {
  let c = p + 1;
  if p == 0 { circle(cx, cy, 8, c); }
  if p == 1 { ring(cx, cy, 8, 3, c); }
  if p == 2 { line(cx - 8, cy - 8, cx + 8, cy + 8, 3, c); line(cx - 8, cy + 8, cx + 8, cy - 8, 3, c); }
  if p == 3 { rect(cx - 8, cy - 8, 16, 16, c); }
  if p == 4 { line(cx - 8, cy, cx + 8, cy, 3, c); line(cx, cy - 8, cx, cy + 8, 3, c); }
  if p == 5 { circle(cx, cy, 8, c); circle(cx, cy, 4, 0); }
  if p == 6 { line(cx - 8, cy + 8, cx, cy - 8, 3, c); line(cx, cy - 8, cx + 8, cy + 8, 3, c); line(cx - 8, cy + 8, cx + 8, cy + 8, 3, c); }
  if p == 7 { rect(cx - 8, cy - 8, 16, 8, c); rect(cx - 8, cy, 16, 8, c); line(cx - 8, cy, cx + 8, cy, 0); }
}

fn scene() {
  for i in 0..16 {
    let x = (i % 4) * 30 + 15;
    let y = (i / 4) * 30 + 15;
    if up[i] || found[i] {
      rect(x - 14, y - 14, 28, 28, 7);
      glyph(cards[i], x, y);
    } else {
      rect(x - 14, y - 14, 28, 28, 10);
      ring(x, y, 6, 2, 11);
    }
  }
  if left == 0 { text("You win", 60, 60, 14, 9); }
}

// A tap on square i of the board.
fn tap(i: int) {
  if found[i] || up[i] || left == 0 { return; }
  if delay > 0 { turnDown(); }           // a wrong pair waits no longer
  if up[i] { return; }
  up[i] = true;
  if first == -1 {
    first = i;
    return;
  }
  moves += 1;
  if cards[first] == cards[i] {
    found[first] = true;
    found[i] = true;
    left -= 1;
    first = -1;
  } else {
    delay = 1000;
  }
}

fn turnDown() {
  for i in 0..16 {
    if up[i] && !found[i] { up[i] = false; }
  }
  first = -1;
  delay = 0;
}

every delay { turnDown(); }

label "Memory";
label "Moves: " + moves;
canvas 120, 120, scene() { tap((y / 30) * 4 + x / 30); }
if left == 8 && !up[0] && !up[1] { button "Start" { start(); } }
```

```app
// 2048: the arrows or the buttons slide the tiles; equal tiles that meet merge; a new tile
// appears after each move that changes the board; no move left ends it. Start begins again.
// icon: fill 3 3 10 3 10 10 3 10 fill 14 3 21 3 21 10 14 10 fill 3 14 10 14 10 21 3 21 fill 14 14 21 14 21 21 14 21
state board = [0; 16];     // the tiles: 0 an empty square, else the number on it
state score = 0;
state over = false;        // a game has run and no move is left
state running = false;     // a game is running now
saved state best = 0;

fn at(x: int, y: int) -> int { return y * 4 + x; }

// The color of a tile by its number.
fn color(v: int) -> int {
  if v == 2 { return 6; }
  if v == 4 { return 3; }
  if v == 8 { return 1; }
  if v == 16 { return 5; }
  if v == 32 { return 2; }
  if v == 64 { return 4; }
  return 9;
}

// The size of the number on a tile.
fn size(v: int) -> int {
  if v < 100 { return 12; }
  if v < 1000 { return 10; }
  return 8;
}

// The board drawn anew from what the game remembers: a square a tile, its number on it.
fn scene() {
  for i in 0..16 {
    let x = (i % 4) * 40;
    let y = (i / 4) * 40;
    if board[i] == 0 {
      rect(x + 1, y + 1, 38, 38, 8);
    } else {
      rect(x + 1, y + 1, 38, 38, color(board[i]));
      text(board[i], x + 20, y + 20, size(board[i]), 0);
    }
  }
  if !running {
    if over { text("Game over", 80, 80, 14, 1); }
    else { text("2048", 80, 80, 20, 9); }
  }
}

// A 2 or a 4 on a random empty square.
fn add() {
  let n = 0;
  for i in 0..16 { if board[i] == 0 { n += 1; } }
  if n == 0 { return; }
  let k = random(n);
  for i in 0..16 {
    if board[i] == 0 {
      if k == 0 {
        board[i] = 2;
        if random(10) == 0 { board[i] = 4; }
        return;
      }
      k -= 1;
    }
  }
}

// Slide one line, front index first; equal tiles that meet merge into their sum.
// Returns the score gained; sets moved if the line changed.
fn line(i0: int, i1: int, i2: int, i3: int) -> int {
  let vs = [board[i0], board[i1], board[i2], board[i3]];
  let n = 0;
  for i in 0..4 { if vs[i] != 0 { vs[n] = vs[i]; n += 1; } }
  let gained = 0;
  let i = 0;
  while i + 1 < n {
    if vs[i] == vs[i + 1] {
      vs[i] += vs[i + 1];
      gained += vs[i];
      remove(vs, i + 1);
      n -= 1;
    }
    i += 1;
  }
  for i in n..4 { vs[i] = 0; }
  if vs[0] != board[i0] || vs[1] != board[i1] || vs[2] != board[i2] || vs[3] != board[i3] {
