// Tetris: Start begins; the arrows or the buttons move, turn and drop the piece; full rows score.
// icon: fill 3 3 9 3 9 9 3 9 fill 12 3 18 3 18 9 12 9 fill 7 12 13 12 13 18 7 18 fill 16 12 22 12 22 18 16 18
state board = [0; 200];       // what has landed: 0 empty, else its color
