fn at(x: int, y: int) -> int { return y * 10 + x; }

// Whether (x, y) is free: inside the sides and empty, or the piece's own square.
fn free(x: int, y: int) -> bool {
  if x < 0 || x >= 10 || y >= 20 { return false; }
  if y < 0 { return true; }
  return board[at(x, y)] == 0;
}

// Whether the piece would fit moved by (mx, my), or turned a quarter.
fn fits(mx: int, my: int, turn: bool) -> bool {
  for i in 0..4 {
    let x = cells[i * 2];
    let y = cells[i * 2 + 1];
    if turn { let t = x; x = y; y = -t; }
    if !free(px + x + mx, py + y + my) { return false; }
  }
  return true;
}

// The piece of kind k: its squares and color.
fn shape(k: int) {
  let cs = [0; 8];
  if k == 0 { cs = [0, 0, 1, 0, 2, 0, 3, 0]; }        // I
  if k == 1 { cs = [0, 0, 1, 0, 0, 1, 1, 1]; }        // O
  if k == 2 { cs = [0, 0, 1, 0, 2, 0, 1, 1]; }        // T
  if k == 3 { cs = [1, 0, 2, 0, 0, 1, 1, 1]; }        // S
  if k == 4 { cs = [0, 0, 1, 0, 1, 1, 2, 1]; }        // Z
  if k == 5 { cs = [0, 0, 0, 1, 0, 2, 1, 2]; }        // J
  if k == 6 { cs = [1, 0, 1, 1, 1, 2, 0, 2]; }        // L
  cells = cs;
  pcol = 1 + k % 6;
}

// A new piece at the top; Game over if it cannot enter.
fn enter() {
  shape(nextk);
  nextk = random(7);
  px = 3;
  py = 0;
  if !fits(0, 0, false) {
    over = true;
    speed = 0;
    best = max(best, score);
  }
}

fn start() {
  clear(board);
  for i in 0..200 { push(board, 0); }
  score = 0;
  over = false;
  nextk = random(7);
  enter();
  speed = 500;
}

// Move or turn, only if it fits.
fn try(mx: int, my: int, turn: bool) {
  if fits(mx, my, turn) {
    px += mx;
    py += my;
    if turn {
      for i in 0..4 {
        let x = cells[i * 2];
        cells[i * 2] = cells[i * 2 + 1];
        cells[i * 2 + 1] = -x;
      }
    }
  }
}

// Land the piece, clear full rows, then a new one.
fn land() {
  for i in 0..4 { board[at(px + cells[i * 2], py + cells[i * 2 + 1])] = pcol; }
  for y in 19..-1 {
    let full = true;
    for x in 0..10 {
      if board[at(x, y)] == 0 { full = false; }
    }
    if full {
      remove(board, at(0, y));
      remove(board, at(0, y));
      insert(board, 0, 0);
      insert(board, 0, 0);
      score += 10;
    }
  }
  enter();
}

// One step down; landing if it cannot.
fn step() {
  if fits(0, 1, false) {
    py += 1;
