```app
// Tic-tac-toe: two players share the board; tap a square to place X or O, X first; New game empties it.
// Without: no score kept between games, no computer opponent.
// icon: line 2 7 10 15 line 10 7 2 15 ring 17 11 4
state cells = [0; 9];   // 0 empty, 1 X, 2 O
state xturn = true;
state msg = "";

fn line3(a: int, b: int, c: int) -> int {
  if cells[a] != 0 && cells[a] == cells[b] && cells[b] == cells[c] { return cells[a]; }
  return 0;
}

fn winner() -> int {
  let w = line3(0, 1, 2);
  if w == 0 { w = line3(3, 4, 5); }
  if w == 0 { w = line3(6, 7, 8); }
  if w == 0 { w = line3(0, 3, 6); }
  if w == 0 { w = line3(1, 4, 7); }
  if w == 0 { w = line3(2, 5, 8); }
  if w == 0 { w = line3(0, 4, 8); }
  if w == 0 { w = line3(2, 4, 6); }
