}

fn status() -> string {
  let w = winner();
  if w == 1 { return "X wins"; }
  if w == 2 { return "O wins"; }
  if full() { return "Draw"; }
  return "";
}

fn drawX(i: int) {
  let cx = (i % 3) * 40 + 20;
  let cy = (i / 3) * 40 + 20;
  line(cx - 10, cy - 10, cx + 10, cy + 10, 3, 1);
  line(cx + 10, cy - 10, cx - 10, cy + 10, 3, 1);
}

fn scene() {
  for i in 1..2 { line(40 * i, 0, 40 * i, 120, 2, 8); }
  for i in 1..2 { line(0, 40 * i, 120, 40 * i, 2, 8); }
  for i in 0..9 {
    if cells[i] == 1 { drawX(i); }
    if cells[i] == 2 { ring((i % 3) * 40 + 20, (i / 3) * 40 + 20, 11, 3, 4); }
  }
  if msg != "" { text(msg, 60, 60, 12, 9); }
}

fn place(i: int) {
  if msg != "" || cells[i] != 0 { return; }
  if xturn { cells[i] = 1; } else { cells[i] = 2; }
  xturn = !xturn;
  msg = status();
}

label "Tic-tac-toe";
canvas 120, 120, scene() { place((y / 40) * 3 + x / 40); }
if msg != "" { button "New game" { clear(cells); xturn = true; msg = ""; } }
if msg == "" { if xturn { label "X to move"; } else { label "O to move"; } }
