// Connect four: tap a column (or press 1-7) to drop your disc; Red moves first, then Yellow.
// Four in a row wins. New game empties the board.
// icon: ring 5 5 3 ring 12 5 3 ring 19 5 3 ring 5 12 3 ring 12 12 3 ring 19 12 3 line 4 19 20 19
state board = [0; 42];      // 0 empty, 1 red, 3 yellow; square 0 top left, 7 a row
state red = true;           // the player to move
state over = false;
state won = 0;              // 1 red won, 3 yellow won

fn at(c: int, r: int) -> int { return r * 7 + c; }

// The lowest empty row of a column, or -1 when it is full.
fn free(c: int) -> int {
  for r in 5..-1 {
    if board[at(c, r)] == 0 { return r; }
  }
  return -1;
}

// Four in a row through (c, r) in a direction?
fn line4(c: int, r: int, dc: int, dr: int) -> bool {
  let n = 1;
  let p = board[at(c, r)];
  for i in 1..4 {
    let x = c + dc * i;
    let y = r + dr * i;
    if x < 0 || x >= 7 || y < 0 || y >= 6 || board[at(x, y)] != p { return n >= 4; }
    n += 1;
  }
  return n >= 4;
}

fn won4(c: int, r: int) -> bool {
  if line4(c, r, 1, 0) { return true; }
  if line4(c, r, 0, 1) { return true; }
  if line4(c, r, 1, 1) { return true; }
  return line4(c, r, 1, -1);
}

// Drop into a column: the disc of the player to move, then the other moves.
fn drop(c: int) {
  if over { return; }
  let r = free(c);
  if r < 0 { return; }
  if red { board[at(c, r)] = 1; } else { board[at(c, r)] = 3; }
  if won4(c, r) {
    over = true;
    won = board[at(c, r)];
  } else {
    red = !red;
  }
}

fn newgame() {
  clear(board);
  for i in 0..42 { board[i] = 0; }
  red = true;
  over = false;
  won = 0;
}

fn disc(c: int, r: int) {
  let p = board[at(c, r)];
  if p != 0 { circle(20 + c * 20, 20 + r * 20, 8, p); }
}

fn scene() {
  rect(10, 10, 140, 120, 4);
  for c in 0..7 {
    for r in 0..6 { disc(c, r); }
  }
  if over {
    if won == 1 { text("Red wins", 80, 6, 8, 1); }
    if won == 3 { text("Yellow wins", 80, 6, 8, 3); }
  } else {
    if red { text("Red to move", 80, 6, 8, 1); }
    else { text("Yellow to move", 80, 6, 8, 3); }
  }
}

label "Connect four";
canvas 160, 140, scene() { drop(x / 20); }
if over { button "New game" { newgame(); } }
