```app
// Calc: type a number with 0 to 9, an operation, another number, then = for the result;
// / rounds toward zero, dividing by 0 shows Error, C clears all.
// icon: loop 3 3 21 3 21 19 5 19 5 8 8 8 8 5 16 5 16 8 line 10 11 18 11 line 14 11 14 15
state cur = 0;            // the number being typed, or the result
state acc = 0;            // the saved left side of a pending operation
state op = "";            // "", "+", "-", "*" or "/"
state fresh = false;      // a digit starts a new number after an operation or =
state err = false;

// The pending line above the display: "12 +" while the right side is typed.
fn pending() -> string {
  if op != "" && !err { return acc + " " + op; }
  return "";
}

// The display: Error, or the number typed so far.
fn shown() -> string {
  if err { return "Error"; }
  return "" + cur;
}

// Apply the pending operation to acc and v; a divide by zero raises Error.
fn apply(v: int) -> int {
  if op == "+" { return acc + v; }
  if op == "-" { return acc - v; }
  if op == "*" { return acc * v; }
  return acc / v;
}

// Take an operation key: finish any pending one, then remember this one.
fn operate(o: string) {
  if err { return; }
  if op != "" && !fresh { cur = apply(cur); }
  if cur == 0 && op == "/" { err = true; return; }
  acc = cur;
  op = o;
  fresh = true;
}

// A digit: start a new number or append to the one being typed (15 digits at most).
fn digit(d: int) {
  if err { return; }
  if fresh {
    cur = d;
    fresh = false;
  } else if cur < 1000000000000000 {
    cur = cur * 10 + d;
  }
}

fn equals() {
  if err || op == "" || fresh { return; }
  if op == "/" && cur == 0 {
    err = true;
    return;
  }
  cur = apply(cur);
  op = "";
  fresh = true;
}

fn clearAll() {
  cur = 0;
  acc = 0;
  op = "";
  fresh = false;
  err = false;
}

label "Calc";
label pending();
label shown();
row {
  button "7" { digit(7); }
  button "8" { digit(8); }
  button "9" { digit(9); }
  button "/" { operate("/"); }
}
row {
  button "4" { digit(4); }
  button "5" { digit(5); }
  button "6" { digit(6); }
  button "*" { operate("*"); }
}
row {
  button "1" { digit(1); }
  button "2" { digit(2); }
  button "3" { digit(3); }
  button "-" { operate("-"); }
}
row {
  button "C" { clearAll(); }
  button "0" { digit(0); }
  button "=" { equals(); }
  button "+" { operate("+"); }
}
