// Life: tap squares to seed them, Step advances one generation, Play runs, Pause stops, Clear empties.
// icon: dot 12 12 8 loop 12 12 5 dot 4 12 2 dot 20 12 2 dot 12 4 2 dot 12 20 2
state board = [0; 400];   // 20 x 20: 1 alive, 0 dead
