// Memory: 16 cards face down; tap two a turn to find 8 pairs; a mismatch hides after a
// second or at your next tap. Fewest moves wins. Best kept between runs.
// icon: fill 5 5 10 5 12 8 19 8 19 19 5 19 fill 14 14 18 14 18 18 14 18
state cards = [0; 16];       // each card's pair, 1..8 twice, shuffled at Start
state up = [false; 16];      // face up
state first = -1;            // the one card turned and waiting, -1 none
state moves = 0;
state wait = 0;              // ticks left before a mismatch hides
state tick = 0;              // ms a tick; 0 while nothing waits
saved state best = 0;

fn won() -> bool {
  for i in 0..16 {
    if !up[i] { return false; }
  }
  return true;
}

fn hide() {
  if first >= 0 { up[first] = false; }
  for i in 0..16 {
    if up[i] && i != first { up[i] = false; }
  }
  first = -1;
  wait = 0;
  tick = 0;
}

fn start() {
  for i in 0..16 { cards[i] = 1 + i / 2; }
  for i in 0..16 {                                  // shuffle: swap each with a random one
    let j = random(16);
    let t = cards[i];
    cards[i] = cards[j];
    cards[j] = t;
    up[i] = false;
  }
  first = -1;
  moves = 0;
  wait = 0;
  tick = 0;
}

fn tap(i: int) {
  if tick > 0 { hide(); }                           // a pending mismatch hides now
  if up[i] || won() { return; }
  up[i] = true;
  if first == -1 {
    first = i;
    return;
  }
  moves += 1;
  if cards[first] == cards[i] {                     // a pair: both stay up
    first = -1;
    if won() { best = min(best, moves); }
  } else {
    wait = 10;                                      // hide them after a second
    tick = 100;
  }
}

