fn ink(v: int) -> int {
  if v <= 4 { return 9; }
  return 0;
}

// The board drawn anew from what it remembers: a square a tile, its number on it.
fn scene() {
  for y in 0..4 {
    for x in 0..4 {
      let i = at(x, y);
      let px = x * 40;
      let py = y * 40;
      if board[i] == 0 {
        rect(px + 1, py + 1, 38, 38, 8);
      } else {
        rect(px + 1, py + 1, 38, 38, color(board[i]));
        text(board[i], px + 20, py + 20, 12, ink(board[i]));
      }
    }
  }
  if !running && score == 0 { text("2048", 80, 80, 24, 11); }
  if !running && score > 0 { text("Game over", 80, 80, 16, 11); }
}

// A 2 or a 4 on a random empty square.
fn spawn() {
  let free = [0; 0];
  for i in 0..16 {
    if board[i] == 0 { push(free, i); }
  }
  if len(free) == 0 { return; }
  let k = free[random(len(free))];
  board[k] = 2;
  if random(10) == 0 { board[k] = 4; }
}

fn start() {
  clear(board);
  score = 0;
  spawn();
  spawn();
  running = true;
}

// The tiles of one line, from the square nearest the edge they move to.
fn line(a: int, b: int, c: int, d: int) -> int {
  return board[a] * 1000 + board[b] * 100 + board[c] * 10 + board[d];
}

fn put(a: int, b: int, c: int, d: int, v: int) {
  board[a] = v / 1000;
  board[b] = (v / 100) % 10;
  board[c] = (v / 10) % 10;
  board[d] = v % 10;
}

// Slide one line toward a; true if it changed. Merged tiles add to the score.
fn slide(a: int, b: int, c: int, d: int) -> bool {
  let old = line(a, b, c, d);
  let t = [0; 0];
  for i in 0..4 {
    let v = (old / pow10(3 - i)) % 10;
    if v > 0 { push(t, v); }
  }
  let m = [0; 0];
  let i = 0;
  while i < len(t) {
    if i + 1 < len(t) && t[i] == t[i + 1] {
      push(m, t[i] * 2);
      score += t[i] * 2;
      i += 2;
    } else {
      push(m, t[i]);
      i += 1;
    }
  }
  let v = 0;
  for j in 0..len(m) { v += m[j] * pow10(3 - j); }
  put(a, b, c, d, v);
  return v != old;
}

fn pow10(n: int) -> int {
  if n == 0 { return 1; }
  if n == 1 { return 10; }
  if n == 2 { return 100; }
  return 1000;
}

// A move in direction (dx, dy): slide each of the 4 lines that way.
fn move(dx: int, dy: int) -> bool {
  let changed = false;
  for k in 0..4 {
    let x0 = 0;
    let y0 = 0;
    let x3 = 0;
    let y3 = 0;
    if dy == 0 {
      y0 = k;
      y3 = k;
      x0 = 3 - 3 * (dx + 1) / 2;
      x3 = 3 * (1 - dx) / 2;
    } else {
      x0 = k;
      x3 = k;
      y0 = 3 - 3 * (dy + 1) / 2;
      y3 = 3 * (1 - dy) / 2;
    }
    if slide(at(x0, y0), at(x0 + dx, y0 + dy), at(x0 + 2 * dx, y0 + 2 * dy), at(x3, y3)) {
      changed = true;
    }
  }
  return changed;
}

// Whether any move is left: an empty square, or two equal tiles that meet.
fn stuck() -> bool {
  for i in 0..16 {
    if board[i] == 0 { return false; }
  }
  for y in 0..4 {
    for x in 0..4 {
      if x < 3 && board[at(x, y)] == board[at(x + 1, y)] { return false; }
      if y < 3 && board[at(x, y)] == board[at(x, y + 1)] { return false; }
    }
  }
  return true;
}

fn go(dx: int, dy: int) {
  if !running { return; }
  if move(dx, dy) {
    spawn();
    if stuck() {
      running = false;
      best = max(best, score);
    }
  }
}

